import pandas as pd
import os
from datetime import datetime
from pandas.errors import EmptyDataError

def task_func(csv_file_path, column_name, date_format="%Y-%m-%d"):
    if not os.path.exists(csv_file_path):
        raise FileNotFoundError(f"No such file or directory: '{csv_file_path}'")

    try:
        df = pd.read_csv(csv_file_path)
    except EmptyDataError:
        return pd.DataFrame()

    if column_name not in df.columns:
        raise ValueError(f"Column '{column_name}' not found in CSV file")

    result = df.copy()
    parsed_dates = pd.to_datetime(result[column_name], format=date_format, errors="coerce")

    if getattr(parsed_dates.dt, "tz", None) is not None:
        parsed_dates = parsed_dates.dt.tz_localize(None)

    today = pd.Timestamp(datetime.now().date())
    mask = parsed_dates.notna() & (parsed_dates >= today)

    result = result.loc[mask].copy()
    result[column_name] = parsed_dates.loc[mask].to_numpy()

    return result.sort_values(by=column_name, ascending=True, kind="mergesort").reset_index(drop=True)
